//! Excluded actual-gallery pagination, editing and logical-data workflow.
use super::grid_worklist_review::gallery_worklist;
use dioxus::prelude::*;
use dioxus_ix::*;

#[component]
pub fn GridPaginationPreview() -> Element {
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_worklist::STYLES} }
        IxTheme { class:"grid-pagination-review",
            gallery_worklist::GridWorklistExample {}
            div { onmounted:move |_| {
                #[cfg(all(feature="desktop",not(target_arch="wasm32")))]
                {let window=window.clone();spawn(async move {
                    let query=crate::dom_query::eval(NATIVE_GRID_PAGINATION_CHECK);let _=query.send("gridpagination");
                    match query.join::<serde_json::Value>().await {
                        Ok(value)if value["ok"]==true=>{println!("Dioxus native Grid pagination: {value}");window.close();}
                        value=>{eprintln!("Dioxus native Grid pagination failed: {value:?}");std::process::exit(1);}
                    }
                });spawn(async move {futures_timer::Delay::new(std::time::Duration::from_secs(40)).await;eprintln!("Grid pagination native replay timed out");std::process::exit(1);});}
            } }
        }
    }
}
const STYLES: &str = "body{margin:0}.grid-pagination-review{box-sizing:border-box;min-height:100vh;padding:24px}@media(max-width:600px){.grid-pagination-review{padding:16px}}";

#[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
const NATIVE_GRID_PAGINATION_CHECK: &str = r#"
let snapshots={};
try {
 await dioxus.recv();
 const get=id=>document.getElementById('worklist-'+id),host=()=>document.getElementById('grid-worklist'),status=()=>get('status'),pg=()=>get('pagination-status'),grid=()=>host()?.querySelector('[role="grid"][aria-label="Maintenance worklist"]'),pager=()=>host()?.querySelector('nav[aria-label="Maintenance worklist pages"]'),fieldset=()=>host()?.querySelector('fieldset.ix-data-grid-pagination');
 const control=label=>pager()?.querySelector('[aria-label="'+label+'"]'),row=id=>grid()?.querySelector('[data-row-id="'+id+'"]'),cell=(id,column)=>row(id)?.querySelector('[role="gridcell"][data-column-id="'+column+'"]'),editor=()=>host()?.querySelector('.ix-data-grid-editor:not([readonly])');
 const assert=(condition,label)=>{if(!condition)throw Error(label)},wait=async(label,predicate)=>{for(let i=0;i<200;i++){if(predicate())return;await new Promise(resolve=>setTimeout(resolve,20))}throw Error(label+'; page='+pg()?.outerHTML+'; state='+status()?.outerHTML)};
 const click=id=>{assert(get(id),id+' exists');get(id).click()},key=(node,value,ctrl=false)=>node.dispatchEvent(new KeyboardEvent('keydown',{key:value,code:value,ctrlKey:ctrl,bubbles:true,cancelable:true}));
 const setInput=async(node,value)=>{Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(node,String(value));node.dispatchEvent(new Event('input',{bubbles:true,composed:true}));await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))};
 const page=async value=>{await setInput(control('Page selection'),value+1);key(control('Page selection'),'Enter');await wait('actual current page '+value,()=>pg().dataset.page===String(value))};
 const size=async value=>{control('Items per page').value=String(value);control('Items per page').dispatchEvent(new Event('change',{bubbles:true}));await wait('current page size '+value,()=>pg().dataset.pageSize===String(value)&&pg().dataset.page==='0')};
 const select=async id=>{row(id).querySelector('[role="checkbox"]').click();await wait(id+' selected',()=>row(id).getAttribute('aria-selected')==='true')};
 const filter=async(value,count)=>{const trigger=grid().querySelector('button[aria-label="Filter Status"]');trigger.click();await wait('actual native filter popup',()=>document.getElementById(trigger.getAttribute('popovertarget'))?.matches(':popover-open'));const popup=document.getElementById(trigger.getAttribute('popovertarget'));await setInput(popup.querySelector('input[aria-label="Status filter value 1"]'),value);await wait('actual filtered '+count,()=>status().dataset.visible===String(count));trigger.click()};
 const snapshot=()=>({page:{...pg().dataset},grid:{...status().dataset},mounted:[...grid().querySelectorAll('.ix-data-grid-body [data-row-id]')].map(n=>({id:n.dataset.rowId,index:n.getAttribute('aria-rowindex')}))});
 await wait('actual default worklist mounted',()=>pg()&&get('pagination')&&row('worklist-000'));assert(pg().dataset.enabled==='false'&&!pager(),'existing worklist starts unpaged');click('pagination');await wait('first page of12',()=>pg().dataset.enabled==='true'&&pg().dataset.page==='0'&&pg().dataset.pageSize==='12'&&pg().dataset.pageCount==='8'&&pager());assert(grid().getAttribute('aria-rowcount')==='97'&&row('worklist-000').getAttribute('aria-rowindex')==='2','full filtered ARIA row count and first global index');control('Next page').click();await wait('second page uses global row index',()=>pg().dataset.page==='1'&&row('worklist-012')?.getAttribute('aria-rowindex')==='14');snapshots.firstAndNext=snapshot();
 await select('worklist-013');await page(0);await select('worklist-001');assert(status().dataset.selected==='2','selection persists across pages');const all=grid().querySelector('[role="checkbox"][aria-label="Select all filtered rows"]');all.click();await wait('header selects entire filtered96 not only page',()=>status().dataset.selected==='96');click('clear-selection');await wait('selection clear',()=>status().dataset.selected==='0');await select('worklist-001');await page(1);await select('worklist-013');click('mark-service');await wait('bulk changes selected current and off-page Warning records',()=>cell('worklist-013','status')?.textContent.includes('Maintenance'));await page(0);assert(cell('worklist-001','status').textContent.includes('Maintenance')&&status().dataset.selected==='2','bulk service includes off-page selected record');snapshots.selection=snapshot();
 await page(7);assert(pg().dataset.start==='84'&&pg().dataset.end==='96','direct page8 covers final12 of96');await size(24);assert(pg().dataset.pageCount==='4'&&pg().dataset.start==='0','size24 resets first page with4pages');await page(1);cell('worklist-024','asset').focus();key(cell('worklist-024','asset'),'End',true);await wait('native CtrlEnd reveals last local page row/column with vertical scroll',()=>document.activeElement===cell('worklist-047','ticket')&&grid().scrollTop>0);const scrolledPage={top:grid().scrollTop,left:grid().scrollLeft};control('Next page').focus();await wait('footer owns native page change focus',()=>document.activeElement===control('Next page'));control('Next page').click();await wait('page change resets native vertical offset and retains horizontal offset',()=>pg().dataset.page==='2'&&grid().scrollTop<=1&&Math.abs(grid().scrollLeft-scrolledPage.left)<=2&&row('worklist-048'));snapshots.scrollReset={before:scrolledPage,after:{top:grid().scrollTop,left:grid().scrollLeft},page:{...pg().dataset}};await page(1);const target=cell('worklist-024','asset');target.focus();key(target,'F2');await wait('page2 active editor guards native pager',()=>editor()&&fieldset().disabled);await setInput(editor(),'Paged asset 024');assert(control('Next page').matches(':disabled')&&control('Page selection').matches(':disabled')&&control('Items per page').matches(':disabled'),'active editor disables every native pager control');control('Next page').click();assert(pg().dataset.page==='1'&&editor().value==='Paged asset 024','disabled navigation cannot discard current draft');key(editor(),'Enter');await wait('commit enables pager and stores edit',()=>!editor()&&!fieldset().disabled&&status().dataset.saved==='1');await page(2);await page(1);assert(cell('worklist-024','asset').textContent.includes('Paged asset 024'),'committed edit survives page departure/return');cell('worklist-024','asset').focus();key(cell('worklist-024','asset'),'F2');await wait('cancel editor active',()=>editor()&&fieldset().disabled);await setInput(editor(),'Discarded page draft');key(editor(),'Escape');await wait('Escape releases pager without saving draft',()=>!editor()&&!fieldset().disabled);assert(cell('worklist-024','asset').textContent.includes('Paged asset 024'),'Escape preserves committed value');snapshots.edited=snapshot();
 await filter('Normal',32);assert(pg().dataset.page==='0'&&pg().dataset.pageCount==='2'&&pg().dataset.total==='32','filter applies before paging and resets first page');await page(1);assert(pg().dataset.start==='24'&&pg().dataset.end==='32','filtered last page has8 rows');const sort=grid().querySelector('button[aria-label="Sort Asset"]');sort.click();await wait('sort resets first filtered page',()=>status().dataset.sort==='asset-ascending'&&pg().dataset.page==='0');await page(1);get('csv-generate').click();await wait('CSV remains full filtered logical result across pages',()=>get('csv-status').dataset.rows==='32');await filter('nothing matches this status',0);await wait('empty result disables page entry',()=>pg().dataset.pageCount==='0'&&control('Page selection').disabled);assert(pg().dataset.start==='0'&&pg().dataset.end==='0','empty page range is truthful');click('clear-filters');await wait('clear filters restores96 first page',()=>pg().dataset.total==='96'&&pg().dataset.page==='0'&&pg().dataset.pageCount==='4');snapshots.filtered=snapshot();
 get('csv-generate').click();await wait('CSV96 remains independent of current page',()=>get('csv-status').dataset.rows==='96');click('pagination');await wait('opt out restores default unpaged presentation',()=>pg().dataset.enabled==='false'&&!pager());assert(status().dataset.selected==='2'&&status().dataset.saved==='1','opt out preserves model edits and selection');click('restore');await wait('Restore returns prior unpaged defaults',()=>pg().dataset.enabled==='false'&&!pager()&&status().dataset.selected==='0'&&status().dataset.saved==='0'&&status().dataset.visible==='96'&&row('worklist-000'));assert(cell('worklist-000','asset').textContent.includes('Asset 000'),'reset actual data restored');snapshots.restored=snapshot();
 return{ok:true,snapshots,checks:['opt-in12-row pages retain full filtered global ARIA indexes; actual Next/directpage/size controls update controlled state','cross-page stable-ID selection/headerall96/bulk service include off-page records','direct final page/size24 are truthful; real scrolled page resets vertical offset and retains horizontal offset; disabled fieldset protects active draft until Enter/Escape','sort/filter apply before page/reset; filteredlast8/empty result/recovery and logicalCSV32 acrosspages work','CSV96 stays full dataset; optout preserves state and Restore returns original unpaged model/selection semantics'],input:'Excluded synthetic DOM input/change/click/key dispatch invokes actual gallery state and native disabled-fieldset behavior. No application state/controller/callback injection; trusted native input is separate Chromium evidence.',renderer:navigator.userAgent};
} catch(error){return{ok:false,error:String(error),snapshots,page:document.getElementById('worklist-pagination-status')?.outerHTML,state:document.getElementById('worklist-status')?.outerHTML}}
"#;
